def ktab(cap,names):
    rows=[]
    for n in names:
        y,did,mem,fall=K[n]
        left=f"{n}<span class='ky'>{y}</span>"
        right=("<span class='kd'>したこと</span><ul class='kl'>"+''.join(f"<li>{d}</li>" for d in did)+"</ul>"
               +(f"<span class='kd'>おもな閣僚</span>{mem}" if mem and mem!='―' else '')
               +f"<span class='kd'>倒れた理由</span>{fall}")
        rows.append(f"<div class='vr'><span>{left}</span><span>{right}</span></div>")
    return ("<div class='viz vtab ktab'><div class='viz-cap'>表 ── "+cap+"</div><div class='vs'><div class='vh'><span>内閣（期間）</span><span>したこと・おもな閣僚・倒れた理由</span></div>"
            +''.join(rows)+"</div></div>")
